application.css:
* { box-sizing: border-box; }

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #25334a;
  background: #eef3f8;
}

body {
  min-width: 320px;
  min-height: 100vh;
  margin: 0;
  background: radial-gradient(circle at 15% 10%, #dcecff 0, transparent 34%), linear-gradient(135deg, #f7faff 0%, #edf3f8 100%);
}

.app-shell { width: min(100% - 32px, 650px); margin: 0 auto; padding: 8vh 0 32px; }
.todo-card { background: rgba(255,255,255,.94); border: 1px solid #e2eaf3; border-radius: 24px; padding: clamp(24px, 5vw, 42px); box-shadow: 0 20px 60px rgba(53, 78, 111, .12); }
.app-header { display: flex; align-items: center; gap: 17px; margin-bottom: 32px; }
.brand-mark { display: grid; place-items: center; width: 52px; height: 52px; border-radius: 16px; color: #fff; background: linear-gradient(145deg, #648cf2, #4769d4); font-size: 29px; font-weight: 700; box-shadow: 0 8px 18px rgba(71,105,212,.25); }
.eyebrow { margin: 0 0 3px; color: #71809a; font-size: 12px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; }
h1 { margin: 0; color: #1e2d45; font-size: clamp(27px, 5vw, 36px); letter-spacing: -.04em; }
.subtitle { margin: 4px 0 0; color: #8290a5; font-size: 14px; }
.task-form { display: flex; gap: 10px; margin-bottom: 34px; }
.task-form input { min-width: 0; flex: 1; padding: 15px 17px; border: 1px solid #dbe4ef; border-radius: 12px; outline: none; color: #26364e; background: #f8fafd; font: inherit; transition: border .2s, box-shadow .2s, background .2s; }
.task-form input:focus { border-color: #6c8eef; background: #fff; box-shadow: 0 0 0 4px rgba(108,142,239,.14); }
.task-form button { border: 0; border-radius: 12px; padding: 0 18px; color: #fff; background: #4e70d8; cursor: pointer; font: inherit; font-weight: 700; white-space: nowrap; transition: transform .15s, background .15s; }
.task-form button:hover { background: #3f61ca; transform: translateY(-1px); }
.task-form button span { margin-left: 5px; font-size: 20px; vertical-align: -1px; }
.list-heading { display: flex; align-items: center; justify-content: space-between; margin-bottom: 12px; }
h2 { margin: 0; color: #35445b; font-size: 16px; }
.count-pill { padding: 5px 10px; border-radius: 20px; color: #5573c9; background: #edf2ff; font-size: 12px; font-weight: 700; }
.task-list { display: grid; gap: 9px; }
.task { display: flex; align-items: center; gap: 12px; min-height: 58px; padding: 10px 12px; border: 1px solid #e8edf4; border-radius: 13px; background: #fff; animation: appear .2s ease-out; }
.task-text { flex: 1; overflow-wrap: anywhere; color: #35445b; font-size: 15px; line-height: 1.4; }
.task[data-completed="true"] .task-text { color: #99a5b5; text-decoration: line-through; }
.complete-button { display: grid; flex: 0 0 auto; place-items: center; width: 25px; height: 25px; border: 2px solid #cbd6e5; border-radius: 50%; color: #fff; background: transparent; cursor: pointer; transition: .2s; }
.complete-button:hover { border-color: #6688e9; }
.task[data-completed="true"] .complete-button { border-color: #6688e9; background: #6688e9; }
.complete-button::after { content: "✓"; opacity: 0; font-size: 14px; font-weight: 800; }
.task[data-completed="true"] .complete-button::after { opacity: 1; }
.delete-button { border: 0; padding: 7px; color: #a5b0bf; background: transparent; cursor: pointer; font-size: 20px; line-height: 1; }
.delete-button:hover { color: #e06c78; }
.empty-state { margin: 25px 0 8px; color: #9aa6b6; text-align: center; font-size: 14px; }
.footer-note { margin: 20px 0 0; color: #9ba8ba; font-size: 12px; text-align: center; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
@keyframes appear { from { opacity: 0; transform: translateY(-5px); } to { opacity: 1; transform: translateY(0); } }
@media (max-width: 480px) { .task-form { flex-direction: column; } .task-form button { min-height: 48px; } .app-shell { width: min(100% - 20px, 650px); padding-top: 28px; } }

application.javascript:
const form = document.getElementById('task-form');
const input = document.querySelector('[data-testid="task-input"]');
const list = document.querySelector('[data-testid="task-list"]');
const count = document.querySelector('[data-testid="incomplete-count"]');
const emptyState = document.getElementById('empty-state');

let tasks = [];

function render() {
  list.replaceChildren();
  tasks.forEach(task => {
    const item = document.createElement('article');
    item.className = 'task';
    item.dataset.testid = 'task';
    item.dataset.completed = String(task.completed);

    const complete = document.createElement('button');
    complete.type = 'button';
    complete.className = 'complete-button';
    complete.dataset.testid = 'task-complete';
    complete.setAttribute('aria-label', task.completed ? 'Mark task incomplete' : 'Mark task complete');
    complete.setAttribute('aria-pressed', String(task.completed));
    complete.addEventListener('click', () => {
      task.completed = !task.completed;
      render();
    });

    const text = document.createElement('span');
    text.className = 'task-text';
    text.dataset.testid = 'task-text';
    text.textContent = task.text;

    const remove = document.createElement('button');
    remove.type = 'button';
    remove.className = 'delete-button';
    remove.dataset.testid = 'task-delete';
    remove.setAttribute('aria-label', 'Delete task');
    remove.innerHTML = '&times;';
    remove.addEventListener('click', () => {
      tasks = tasks.filter(entry => entry.id !== task.id);
      render();
    });

    item.append(complete, text, remove);
    list.appendChild(item);
  });

  const incomplete = tasks.filter(task => !task.completed).length;
  count.textContent = incomplete;
  emptyState.hidden = tasks.length > 0;
}

form.addEventListener('submit', event => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) {
    input.focus();
    return;
  }
  tasks.push({ id: Date.now() + Math.random(), text, completed: false });
  input.value = '';
  render();
  input.focus();
});

render();
